<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {loadRecords,removeRecord,updateRecord,exportRecords,importRecords,importLegacyWeb,type LeadRecord} from '../scout/persistence';
import {STATUS_LABEL,SERVICE_LABEL,type LeadStatus} from '../scout/opportunity';
import {openExternal} from '../utils/tauriBridge';
const records=ref<LeadRecord[]>([]),filter=ref<'all'|LeadStatus>('all'),search=ref(''),error=ref(''),message=ref('');
const activeId=ref<string|null>(null),note=ref(''),followup=ref(''),amount=ref(0);
const fileInput=ref<HTMLInputElement|null>(null);
const filtered=computed(()=>records.value.filter(r=>(filter.value==='all'||r.status===filter.value)&& `${r.opportunity.candidate.name} ${r.note}`.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>(b.opportunity.score??-1)-(a.opportunity.score??-1)));
const active=computed(()=>records.value.find(r=>r.id===activeId.value));
const date=(s:string)=>new Date(s).toLocaleDateString('ru-RU');
async function reload(){try{records.value=await loadRecords()}catch(e){error.value=String(e)}}onMounted(reload);
async function status(r:LeadRecord,value:LeadStatus){try{records.value=await updateRecord(r.id,{status:value});message.value='Статус обновлён'}catch(e){error.value=String(e)}}
function inspect(r:LeadRecord){activeId.value=r.id;note.value=r.note;followup.value=r.followUpAt?.slice(0,10)||'';amount.value=r.valueRub||0}
async function save(){if(!active.value)return;try{records.value=await updateRecord(active.value.id,{note:note.value,followUpAt:followup.value||'',valueRub:Math.max(0,Number(amount.value)||0)});activeId.value=null;message.value='Карточка сохранена'}catch(e){error.value=String(e)}}
async function remove(r:LeadRecord){if(!confirm(`Удалить ${r.opportunity.candidate.name} из CRM?`))return;try{records.value=await removeRecord(r.id);message.value='Контакт удалён'}catch(e){error.value=String(e)}}
function download(name:string,text:string,type:string){const a=document.createElement('a');const blob=new Blob([text],{type});a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function exportJson(){download('ASV-Scout-3-CRM.json',exportRecords(records.value),'application/json;charset=utf-8')}
function exportCsv(){const escape=(s:unknown)=>`"${String(s??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')}"`;const lines=[['id','artist','lead_type','opportunity_score','status','offer','first_seen','follow_up','revenue_rub','note','evidence_url'].join(',')];for(const r of records.value){const o=r.opportunity;lines.push([r.id,o.candidate.name,o.kind,o.score,r.status,o.service?SERVICE_LABEL[o.service]:'',r.firstSeen,r.followUpAt||'',r.valueRub||'',r.note,o.signals[0]?.url||''].map(escape).join(','))}download('ASV-Scout-3-CRM.csv','\ufeff'+lines.join('\r\n'),'text/csv;charset=utf-8')}
async function importFile(e:Event){const el=e.target as HTMLInputElement;const file=el.files?.[0];if(!file)return;try{const result=await importRecords(await file.text());records.value=result.records;message.value=`Импортировано ${result.imported} контактов`}catch(err){error.value=String(err)}finally{el.value=''}}
async function importOld(){try{const count=await importLegacyWeb();await reload();message.value=`Импортировано ${count} контактов без оценок. Неоднозначные ID доступны в разделе «Архив CRM»`}catch(e){error.value=String(e)}}
async function open(url:string){try{await openExternal(url)}catch(e){error.value=String(e)}}
</script>
<template>
<section class="page">
  <div class="page-heading"><div class="heading"><p class="eyebrow">ASV PRODUCTION / PIPELINE</p><h1>Клиенты <span class="accent">и диалоги.</span></h1><p>Ручное управление контактами, задачами и подтверждёнными заказами.</p></div><div class="toolbar"><button class="button" @click="exportCsv">↓ CSV</button><button class="button" @click="exportJson">↓ JSON</button><button class="button ghost" @click="fileInput?.click()">↑ Импорт</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importFile" /></div></div>
  <div v-if="error" class="warning">{{error}}</div><div v-if="message" class="notice">{{message}}</div>
  <div class="panel mb"><div class="filterbar" style="margin:0"><select v-model="filter" class="field select" style="max-width:195px"><option value="all">Все статусы</option><option v-for="(label,key) in STATUS_LABEL" :key="key" :value="key">{{label}}</option></select><input v-model="search" class="field narrow" placeholder="Поиск по CRM…" /><span class="push"></span><button class="button small" @click="importOld">Импорт старой CRM</button></div></div>
  <div v-if="!filtered.length" class="panel empty"><div class="empty-icon">▦</div><strong>Пока нет контактов</strong><p>Найдите первую коммерческую возможность через радар и изменяйте статусы по мере переговоров.</p><router-link class="button primary" to="/radar">Перейти в радар</router-link></div>
  <div v-else class="panel" style="padding:0;overflow:hidden"><div class="crm-head"><span>Артист / потребность</span><span>Приоритет</span><span>Статус</span><span>Следующий шаг</span><span></span></div><div v-for="r in filtered" :key="r.id" class="crm-row"><div class="crm-person"><strong>{{r.opportunity.candidate.name}}</strong><small>{{r.opportunity.kind==='hot'?'HOT · ':r.opportunity.kind==='growth'?'GROWTH · ':'ПРОВЕРИТЬ · '}}{{r.opportunity.reasons[0]}}</small></div><div class="crm-score">{{r.opportunity.score??'—'}} <small>/100</small></div><div><select class="field select" :value="r.status" @change="status(r,($event.target as HTMLSelectElement).value as LeadStatus)"><option v-for="(label,key) in STATUS_LABEL" :key="key" :value="key">{{label}}</option></select></div><div class="crm-follow"><strong v-if="r.followUpAt">{{date(r.followUpAt)}}</strong><small v-else>Не назначено</small><small v-if="r.valueRub">Сумма: {{r.valueRub.toLocaleString('ru-RU')}} ₽</small></div><div class="crm-buttons"><button class="button small" @click="inspect(r)">Детали</button><button class="button small ghost" @click="open(r.opportunity.candidate.profileUrl)">↗</button></div></div></div>
  <p class="muted-note mt">Контакты не получают сообщений автоматически. Данные веб-версии находятся только в браузере; в Tauri используется локальная SQLite.</p>
  <div v-if="activeId && active" class="modal-backdrop" @click.self="activeId=null"><div class="panel modal" role="dialog" aria-modal="true" aria-label="Карточка CRM"><div class="panel-header"><h2>{{active.opportunity.candidate.name}}</h2><button class="button small ghost" @click="activeId=null">✕</button></div><div class="lead-tags"><span :class="['chip',active.opportunity.kind]">{{active.opportunity.kind.toUpperCase()}}</span><span class="chip">{{STATUS_LABEL[active.status]}}</span></div><div class="field-group"><label>Заметки и результат общения</label><textarea v-model="note" class="field"></textarea></div><div class="details-grid"><div class="field-group"><label>Следующий контакт</label><input v-model="followup" class="field" type="date" /></div><div class="field-group"><label>Фактическая сумма заказа, ₽</label><input v-model.number="amount" class="field" type="number" min="0" step="100" /></div></div><div v-if="active.opportunity.signals.length" class="field-group"><label>Публикация-повод</label><button class="text-link" style="text-align:left" @click="open(active.opportunity.signals[0].url)">{{active.opportunity.signals[0].url}} ↗</button></div><div class="divider"></div><strong style="font-size:13px">Журнал взаимодействий</strong><div class="history mt"><div v-for="(entry,i) in [...active.history].reverse().slice(0,20)" :key="i" class="history-row">{{entry.text}}<small>{{date(entry.at)}}</small></div></div><div class="toolbar mt"><button class="button primary" @click="save">Сохранить</button><button class="button ghost" @click="activeId=null">Закрыть</button><span style="flex:1"></span><button class="button danger" @click="remove(active);activeId=null">Удалить</button></div></div></div>
</section>
</template>
<style scoped>
.crm-head,.crm-row{display:grid;grid-template-columns:minmax(180px,2fr) 85px minmax(145px,1fr) minmax(125px,1fr) 140px;gap:15px;align-items:center;padding:15px 18px}.crm-head{background:#142127;color:#78949a;font-size:11px;letter-spacing:.08em;text-transform:uppercase;border-bottom:1px solid #2c4248}.crm-row{border-bottom:1px solid #23363d}.crm-row:last-child{border:0}.crm-person{min-width:0}.crm-person strong{display:block;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.crm-person small{display:block;font-size:11px;color:#819ba0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px}.crm-score{color:#2ec4b6;font-size:22px;font-weight:780}.crm-score small{font-size:10px;color:#92a7ad}.crm-follow strong,.crm-follow small{display:block;font-size:12px;color:#b2c4c7}.crm-follow small{font-size:11px;color:#829ba0;margin-top:3px}.crm-buttons{display:flex;gap:5px}.modal-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.75);display:grid;place-items:center;z-index:50;padding:16px}.modal{max-height:90vh;overflow:auto;width:min(580px,100%)}.details-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.crm-row .field{padding:8px;font-size:12px;min-height:34px}@media(max-width:980px){.crm-head{display:none}.crm-row{grid-template-columns:1fr 80px;gap:8px;padding:15px}.crm-row>div:nth-child(n+3){grid-column:1/-1}.crm-row .crm-buttons{grid-column:1/-1}.crm-person{max-width:100%}}@media(max-width:510px){.details-grid{grid-template-columns:1fr}}
</style>
